WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, ship_to.city AS ship_city, ship_to.country AS ship_country, COALESCE(attributes['utm_source'], 'direct') AS utm_source_or_default FROM carts WHERE HOUR(created_at) BETWEEN 11 AND 17) SELECT id, created_at, coupon_codes, utm_source_or_default, LAST_VALUE(ship_city) IGNORE NULLS OVER (ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_ship_city FROM unpacked
